<?php
declare(strict_types=1);require __DIR__.'/bootstrap_saas.php';$db=saas_db();$accountId=(int)($_SESSION['passenger_account_id']??0);$profileId=(int)($_SESSION['passenger_profile_id']??0);if(!$accountId||!$profileId)saas_redirect('passenger_auth.php');$error='';$ok='';
$q=$db->prepare("SELECT pa.id,pa.organization_id,pp.* FROM passenger_accounts pa JOIN passenger_profiles pp ON pp.id=pa.passenger_profile_id WHERE pa.id=? AND pp.id=? AND pa.status='ACTIVE' LIMIT 1");$q->execute([$accountId,$profileId]);$me=$q->fetch();if(!$me)saas_redirect('passenger_auth.php');
if($_SERVER['REQUEST_METHOD']==='POST'){try{saas_check_csrf();$name=trim((string)($_POST['full_name']??''));$phone=trim((string)($_POST['phone']??''));$dob=trim((string)($_POST['date_of_birth']??''));$gender=trim((string)($_POST['gender']??''));$address=trim((string)($_POST['address']??''));if($name==='')throw new RuntimeException('Full name is required.');if($dob!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$dob))throw new RuntimeException('Invalid date of birth.');$q=$db->prepare('UPDATE passenger_profiles SET full_name=?,phone=?,date_of_birth=?,gender=?,address=? WHERE id=? AND organization_id=?');$q->execute([$name,$phone?:null,$dob?:null,$gender?:null,$address?:null,$profileId,(int)$me['organization_id']]);$db->prepare('UPDATE passenger_accounts SET phone=? WHERE id=? AND passenger_profile_id=?')->execute([$phone?:null,$accountId,$profileId]);$ok='Profile updated.';$me=array_merge($me,['full_name'=>$name,'phone'=>$phone,'date_of_birth'=>$dob,'gender'=>$gender,'address'=>$address]);}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Profile</title><style>body{font-family:Arial,sans-serif;background:#f4f7fb;margin:0;color:#172033}.wrap{max-width:600px;margin:35px auto;padding:16px}.card{background:#fff;border-radius:16px;padding:22px;box-shadow:0 7px 28px #0001}label{display:block;font-weight:700;margin:12px 0 6px}input,textarea,button{width:100%;padding:11px;border:1px solid #d0d5dd;border-radius:9px;font:inherit}textarea{min-height:90px}button{background:#155eef;color:#fff;border-color:#155eef;font-weight:700;margin-top:15px}.msg{padding:11px;border-radius:9px;margin-bottom:12px}.ok{background:#ecfdf3;color:#067647}.err{background:#fef3f2;color:#b42318}.muted{color:#667085;font-size:13px}a{color:#155eef}</style></head><body><main class="wrap"><div class="card"><p><a href="passenger_dashboard.php">← My Tours</a></p><h1>My Profile</h1><?php if($ok):?><div class="msg ok"><?=saas_h($ok)?></div><?php endif;?><?php if($error):?><div class="msg err"><?=saas_h($error)?></div><?php endif;?><p class="muted">Identity and booking history remain controlled by the tour system. You can update your reusable contact/profile information here.</p><form method="post"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><label>Email</label><input value="<?=saas_h($me['email']??'')?>" disabled><label>Full name</label><input name="full_name" value="<?=saas_h($me['full_name'])?>" required><label>Phone</label><input name="phone" value="<?=saas_h($me['phone']??'')?>"><label>Date of birth</label><input type="date" name="date_of_birth" value="<?=saas_h($me['date_of_birth']??'')?>"><label>Gender</label><input name="gender" value="<?=saas_h($me['gender']??'')?>"><label>Address</label><textarea name="address"><?=saas_h($me['address']??'')?></textarea><button>Save profile</button></form></div></main></body></html>